rofile.CockpitColors) do cockpitColors[key]=value end; cockpitColors.FrontLights=cockpitColors.FrontLights or Color3.fromRGB(252,250,255); cockpitColors.RearLights=cockpitColors.RearLights or Color3.fromRGB(255,116,116)\n\tPaintClient.ApplyColors(vehicle,cockpitColors,true,{Profile=profile}); VehicleCosmetics.ApplyPresentation(vehicle,currentVehicle)\n\tlocal installed=vehicle:FindFirstChild(\"INSTALLED_MODULES_Runtime\")\n\tif installed then for slotId in pairs(profile.InstalledModules or {}) do local prefix=\"PREVIEW_\"..tostring(slotId)..\"_\"; for _,clone in ipairs(installed:GetChildren()) do if string.sub(clone.Name,1,#prefix)==prefix then PaintClient.ApplyColors(clone,PreviewVehicleController.ModuleColors(profile,slotId),(profile.NeonOwned or {})[slotId]==true,{Profile=profile}) end end end end\n\treturn true\nend\nreturn PreviewVehicleController\n"},{"path":["ReplicatedStorage","Modules","Game","Vehicles","Performance","PerformanceRuntime"],"before":"local Definitions = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Vehicles\"):WaitForChild(\"Performance\"):WaitForChild(\"PerformanceDefinitions\"))\nlocal Calculator = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Vehicles\"):WaitForChild(\"Performance\"):WaitForChild(\"PerformanceCalculator\"))\nlocal UpgradeRuntime = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Vehicles\"):WaitForChild(\"Performance\"):WaitForChild(\"PerformanceUpgradeRuntime\"))\nlocal DynamicsAdapter = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"Vehicles\"):WaitForChild(\"Performance\"):WaitForChild(\"PerformanceDynamics\"))\n\nlocal Runtime = {}\n\nlocal function finite(value, fallback)\n\treturn typeof(value) == \"number\" and value == value and value > -math.huge and value < math.huge and value or fallback\nend\n\nfunction Runtime.ZeroRaw()\n\tlocal raw = {}\n\tfor _, name in ipairs(Definitions.RawVariableOrder) do raw[name] = 0 end\n\treturn raw\nend\n\nfunction Runtime.ReadComponentRaw(item)\n\tlocal raw = Runtime.ZeroRaw()\n\tfor _, name in ipairs(Definitions.RawVariableOrder) do\n\t\traw[name] = finite(item and item:GetAttribute(name), finite(item and item:GetAttribute(\"PerformanceDelta_\" .. name), 0))\n\tend\n\treturn raw\nend\n\nfunction Runtime.ReadRuntimeRaw(vehicle)\n\tlocal raw = Runtime.ZeroRaw()\n\tlocal folder = vehicle and vehicle:FindFirstChild(\"RAW_PERFORMANCE_Runtime\")\n\tfor _, name in ipairs(Definitions.RawVariableOrder) do\n\t\tlocal valueObject = folder and folder:FindFirstChild(name)\n\t\traw[name] = finite(valueObject and valueObject:IsA(\"NumberValue\") and valueObject.Value,\n\t\t\tfinite(vehicle and vehicle:GetAttribute(\"Performance_\" .. name), 0))\n\tend\n\treturn raw\nend\n\nfunction Runtime.AddRaw(target, source)\n\tfor _, name in ipairs(Definitions.RawVariableOrder) do target[name] = finite(target[name], 0) + finite(source and source[name], 0) end\n\treturn target\nend\n\nfunction Runtime.CalculateComponents(cockpit, modules, allocationsByModuleId)\n\tlocal raw = Runtime.ReadComponentRaw(cockpit)\n\tfor _, module in ipairs(modules or {}) do\n\t\tlocal moduleId = tostring(module:GetAttribute(\"ModuleId\") or module.Name)\n\t\tlocal allocation = allocationsByModuleId and allocationsByModuleId[moduleId]\n\t\tRuntime.AddRaw(raw, UpgradeRuntime.ApplyToModuleRaw(module, allocation))\n\tend\n\treturn Calculator.Calculate(raw)\nend\n\nfunction Runtime.CalculateRuntimeVehicle(vehicle)\n\treturn Calculator.Calculate(Runtime.ReadRuntimeRaw(vehicle))\nend\n\nfunction Runtime.CompatibilityView(result)\n\tlocal headline, overall, raw = result.Headline or {}, result.Overall or {}, result.Raw or {}\n\treturn {\n\t\tOverall = { Tier = overall.Tier, PerformanceIndex = overall.PerformanceIndex, InternalPerformanceIndex = ov